import sys,json,subprocess
# use fixture one-followup and validate keys of output manually
import pathlib
case=json.load(open('examples/fixtures.json'))[1]
p=subprocess.run([sys.executable,'-I','-B','submission/campaign.py'],input=json.dumps(case['input']).encode(),stdout=subprocess.PIPE)
