assert set(out)=={'manifest','rejected','snapshots','active_requests','plan'}
for m in out['manifest']:assert set(m)=={'lease','probe','target'}
for s in out['snapshots']:
 assert set(s)=={'at','ledger','unbound_applications','leases'}
 assert set(s['ledger'])=={'live','deleted','conflict'}
 for L in s['leases']:
  assert set(L)=={'lease','state','conflicts','internal','external','unresolved','services'}
  for sv in L['services']:assert set(sv)=={'id','internal_open','internal_closed','external_open','external_closed','internal_only','protocol_errors'}
for a in out['active_requests']:assert set(a)=={'id','active'} and type(a['active']) is bool
